PAIRS = [("function openCardFromRead(id){\n  appMode = 'cards';\n  jumpToRelated(id);\n  window.scrollTo(0,0);\n}", "let navStack = [];\nfunction navPush(rec){ navStack.push(rec || {mode: appMode, y: window.scrollY}); try{ history.pushState({n: navStack.length}, ''); }catch(e){} }\nfunction backBtn(on){\n  let b = document.getElementById('backFab');\n  if(!on){ if(b) b.remove(); return; }\n  if(!b){ b = document.createElement('button'); b.id = 'backFab'; b.textContent = '← 읽기로 돌아가기';\n    b.style.cssText = 'position:fixed;left:50%;bottom:18px;transform:translateX(-50%);z-index:50;padding:12px 20px;border-radius:24px;border:0;background:#2b2b2b;color:#fff;font-size:15px;box-shadow:0 4px 12px rgba(0,0,0,.25)';\n    b.onclick = ()=>{ try{ history.back(); }catch(e){ navBack(); } };\n    document.body.appendChild(b); }\n}\nfunction navBack(){\n  const s = navStack.pop(); backBtn(false);\n  if(!s){ if(appMode!=='home'){ appMode = 'home'; render(); window.scrollTo(0,0); } return; }\n  appMode = s.mode; render();\n  if(s.id){ const el = document.getElementById('rc_'+s.id); if(el) el.scrollIntoView({block:'center'}); else window.scrollTo(0, s.y||0); }\n  else window.scrollTo(0, s.y||0);\n}\nwindow.addEventListener('popstate', navBack);\nfunction openCardFromRead(id){\n  navPush({mode: 'read', y: window.scrollY, id: id});\n  appMode = 'cards';\n  jumpToRelated(id);\n  window.scrollTo(0,0);\n  backBtn(true);\n}"), ('function setMode(m){ flushNote(); appMode = m;', 'function setMode(m){ flushNote(); backBtn(false); if(m!==appMode) navPush(); appMode = m;'), ("function goRead(s, f){ appMode = 'read';", "function goRead(s, f){ backBtn(false); if(appMode!=='read') navPush(); appMode = 'read';")]
